-- 제공 자료 기준: 2026-10-26
SET @fg_research = CONVERT( USING utf8mb4);
-- 기관 또는 guide- 상담 업무가 없으면 NOT NULL 제약으로 중단한다.
-- 임시 테이블은 현재 DB 연결에서만 사용한다.
CREATE TEMPORARY TABLE fg_refresh_20261026 (
    institution_id BIGINT NOT NULL PRIMARY KEY,
    sample_service_id BIGINT NOT NULL,
    payload JSON NOT NULL
) ENGINE=InnoDB;

START TRANSACTION;

INSERT INTO fg_refresh_20261026 (
    institution_id, sample_service_id, payload
)
SELECT
    i.institution_id,
    (
        SELECT MIN(s.service_id)
        FROM institution_services s
        WHERE s.institution_id = i.institution_id
          AND s.service_code = CONCAT(
              'guide-', COALESCE(s.topic_code, 'administration')
          )
    ),
    JSON_EXTRACT(
        @fg_research, CONCAT('$[', d.row_no - 1, ']')
    )
FROM JSON_TABLE(
    @fg_research, '$[*]' COLUMNS (
        row_no FOR ORDINALITY,
        code VARCHAR(80) PATH '$.code'
            ERROR ON EMPTY ERROR ON ERROR
    )
) d
LEFT JOIN support_institutions i
    ON i.institution_code = d.code;

-- 원문·대표 키워드·추가 번호·출처를 갱신한다.
-- 기존 분야별 검색 키워드와 상담 역할 연결은 유지한다.
UPDATE support_institutions i
JOIN fg_refresh_20261026 r
    ON r.institution_id = i.institution_id
SET
    i.guidance_data = r.payload->'$.source',
    i.institution_name = r.payload->>'$.source.name',
    i.phone = r.payload->>'$.primaryPhone',
    i.additional_phones = r.payload->'$.additionalPhones',
    i.website_url = r.payload->>'$.source.detail."공식홈페이지"',
    i.address = r.payload->>'$.source.detail."기관소재지"',
    i.target_description = r.payload->>'$.source.detail."상담대상"',
    i.additional_notes = r.payload->>'$.source.detail."중요안내"',
    i.featured_keywords = r.payload->'$.keywords',
    i.source_url = r.payload->>'$.source.sources[0]',
    i.additional_source_urls = JSON_REMOVE(
        r.payload->'$.source.sources', '$[0]'
    ),
    i.as_of = '2026-10-26',
    i.checked_at = '2026-10-26 00:00:00',
    i.verification_status = 'partial';

-- 전화·방문·특별 업무를 분리한다.
-- 원문에서 공통 운영 여부를 확정할 수 없으면 SQL NULL로 저장한다.
UPDATE institution_services s
JOIN fg_refresh_20261026 r
    ON r.institution_id = s.institution_id
JOIN JSON_TABLE(
    r.payload, '$' COLUMNS (
        phone_weekend INT PATH '$.phoneWeekend',
        phone_holiday INT PATH '$.phoneHoliday',
        visit_available INT PATH '$.visitAvailable',
        online_available INT PATH '$.onlineAvailable',
        reservation_available INT PATH '$.reservationAvailable',
        reservation_required INT PATH '$.reservationRequired',
        visit_weekend INT PATH '$.visitWeekend',
        visit_holiday INT PATH '$.visitHoliday',
        special_hours VARCHAR(1000) PATH '$.specialHours',
        special_scope VARCHAR(1000) PATH '$.specialScope',
        special_weekend INT PATH '$.specialWeekend',
        special_holiday INT PATH '$.specialHoliday'
    )
) d ON TRUE
SET
    s.phone_available = 1,
    s.phone = r.payload->>'$.primaryPhone',
    s.phone_hours = r.payload->>'$.source.detail."전화상담시간"',
    s.phone_weekend_available = d.phone_weekend,
    s.phone_holiday_available = d.phone_holiday,
    s.phone_region_status = 'unrestricted',
    s.visit_available = d.visit_available,
    s.visit_address = r.payload->>'$.source.detail."실제방문장소"',
    s.opening_hours = r.payload->>'$.source.detail."방문상담시간"',
    s.visit_weekend_available = d.visit_weekend,
    s.visit_holiday_available = d.visit_holiday,
    s.visit_region_status = 'unknown',
    s.reservation_available = d.reservation_available,
    s.visit_reservation_required = d.reservation_required,
    s.reservation_url = NULL,
    s.branch_information = r.payload->>'$.source.detail."방문지사_예약안내"',
    s.language_notes = r.payload->>'$.languageNotes',
    s.contact_description = r.payload->>'$.source.detail."상담이용절차"',
    s.target_description = r.payload->>'$.source.detail."상담대상"',
    s.online_available = d.online_available,
    s.online_url = NULL,
    s.special_phone_hours = d.special_hours,
    s.special_phone_scope = d.special_scope,
    s.special_phone_weekend_available = d.special_weekend,
    s.special_phone_holiday_available = d.special_holiday,
    s.language_status = CASE
        WHEN JSON_LENGTH(r.payload->'$.languages') > 0
            THEN 'published'
        ELSE 'unknown'
    END,
    s.source_url = r.payload->>'$.source.sources[0]',
    s.as_of = '2026-10-26',
    s.checked_at = '2026-10-26 00:00:00'
WHERE s.service_code = CONCAT(
    'guide-', COALESCE(s.topic_code, 'administration')
);

-- 이번 조사 대상의 기존 언어 연결을 최신 목록으로 교체한다.
-- 기본 6개 언어 외의 언어를 일괄 삭제하는 작업이 아니다.
DELETE l
FROM institution_service_languages l
JOIN institution_services s
    ON s.service_id = l.service_id
JOIN fg_refresh_20261026 r
    ON r.institution_id = s.institution_id
WHERE s.service_code = CONCAT(
    'guide-', COALESCE(s.topic_code, 'administration')
);

INSERT INTO institution_service_languages (
    service_id, language_code, consultation_method, description
)
SELECT
    s.service_id,
    d.language_code,
    'phone',
    CONCAT(
        r.payload->>'$.source.detail."전화지원언어"',
        ' / ',
        r.payload->>'$.languageNotes'
    )
FROM institution_services s
JOIN fg_refresh_20261026 r
    ON r.institution_id = s.institution_id
JOIN JSON_TABLE(
    r.payload, '$.languages[*]' COLUMNS (
        language_code VARCHAR(35) PATH '$'
    )
) d ON TRUE
WHERE s.service_code = CONCAT(
    'guide-', COALESCE(s.topic_code, 'administration')
);

-- 외국인력상담센터의 사무실 주소를 내방상담 장소로 간주했던 연결만 해제한다.
-- 기관 사무실 주소와 지역 마스터는 유지한다.
DELETE sr
FROM institution_service_regions sr
JOIN institution_services s
    ON s.service_id = sr.service_id
JOIN fg_refresh_20261026 r
    ON r.institution_id = s.institution_id
WHERE r.payload->>'$.code' = 'foreign-worker'
  AND sr.consultation_method = 'visit'
  AND s.service_code = CONCAT(
      'guide-', COALESCE(s.topic_code, 'administration')
  );

COMMIT;

DROP TEMPORARY TABLE fg_refresh_20261026;
SET @fg_research = NULL;